from __future__ import annotations

import pytest

from llm_router import LLMRouter, Model, Provider, RouterProfile
from tests.llm_router.support.fault_server import (
    ScriptedHTTPServer,
    ScriptedResponse,
)
from tests.llm_router.support.workers.retry import openai_chat_path
from tests.llm_router.support.workers.tool_failure import openai_tool_call_response
from tests.llm_router.support.workers.worker_patches import patched_openai_sdk

pytestmark = pytest.mark.verification_kind("unit")

_PATH = openai_chat_path()


def lookup(*, value: str) -> dict[str, str]:
    """Return a trivial payload."""
    return {"value": value}


def _tool_response(value: str) -> ScriptedResponse:
    return ScriptedResponse(
        status_code=200,
        headers={"Content-Type": "application/json"},
        body=openai_tool_call_response(
            tool_name="lookup",
            args={"value": value},
        ),
    )


@pytest.mark.verifies("REQ_TOOL_RUNTIME_SAFETY[revision==1]")
def test_round_limit_reached_after_one_round_keeps_next_call_outstanding(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    monkeypatch.setenv("OPENROUTER_API_KEY_1", "test-credential")
    routes = {
        ("POST", _PATH): [
            _tool_response("widget-42"),
            _tool_response("widget-43"),
        ]
    }
    with ScriptedHTTPServer(port=0, routes=routes) as server:
        with patched_openai_sdk(
            forced_base_url=f"{server.base_url}/v1",
            disable_sdk_retries=True,
        ):
            response = LLMRouter(
                RouterProfile(
                    provider=Provider.OPENROUTER,
                    model=Model.DEEPSEEK_V3,
                ),
                temperature=0.0,
                seed=42,
            ).query(
                "Look something up.",
                tools=[lookup],
                tool_choice="required",
                max_tool_rounds=1,
            )
        request_count = server.request_count("POST", _PATH)

    assert request_count == 2
    assert len(response.tool_trace) == 1
    step = next(iter(response.tool_trace))
    assert step.tool_name == "lookup"
    assert step.args == {"value": "widget-42"}
    assert step.result == {"value": "widget-42"}
    outstanding_args = [call.args for call in response.tool_calls]
    assert {"value": "widget-43"} in outstanding_args
    assert {"value": "widget-42"} not in outstanding_args
